package com.nextstep;

import java.awt.Color;
import java.util.concurrent.ThreadLocalRandom;

/** Content for one celebration popup. */
public class Celebration
{
	static final Color GOLD = new Color(255, 200, 60);
	static final Color GREEN = new Color(90, 220, 110);
	static final Color PURPLE = new Color(190, 120, 255);
	static final Color BLUE = new Color(100, 180, 255);

	private static final String[] CHEERS = {
		"Gz!",
		"Big moves.",
		"The grind pays off.",
		"Another one!",
		"Zezima would be proud.",
		"Look at you go!",
		"Absolutely cracked.",
		"Your bank thanks you.",
		"That's a clip.",
		"Main character energy."
	};

	private final String title;
	private final String subtitle;
	private final String detail;
	private final String cheer;
	private final Color color;

	private Celebration(String title, String subtitle, String detail, Color color)
	{
		this.title = title;
		this.subtitle = subtitle;
		this.detail = detail;
		this.cheer = CHEERS[ThreadLocalRandom.current().nextInt(CHEERS.length)];
		this.color = color;
	}

	static Celebration questDone(Suggestion s)
	{
		return new Celebration("Quest complete!", s.getName(), s.getReward(), GOLD);
	}

	static Celebration unlocked(Suggestion s)
	{
		String title;
		switch (s.getType())
		{
			case QUEST:
				title = "Quest unlocked!";
				break;
			case METHOD:
				title = "New method unlocked!";
				break;
			case MINIGAME:
				title = "Minigame unlocked!";
				break;
			default:
				title = "New unlock!";
		}
		return new Celebration(title, s.getName(), s.getReward(), GREEN);
	}

	static Celebration goal(Suggestion s)
	{
		return new Celebration("Goal reached!", s.getName(), "You set it. You did it.", PURPLE);
	}

	static Celebration batch(int count)
	{
		return new Celebration(count + " new unlocks!", "Your account just grew", "Open the Next Step panel to see them", GREEN);
	}

	static Celebration rankUp(Rank rank)
	{
		return new Celebration("Rank up!", "You are now: " + rank.getDisplayName(), "Keep climbing.", rank.getColor());
	}

	static Celebration preview()
	{
		return new Celebration("Quest complete!", "Next Step preview", "This is what finishing things feels like", GOLD);
	}

	public String getTitle()
	{
		return title;
	}

	public String getSubtitle()
	{
		return subtitle;
	}

	public String getDetail()
	{
		return detail;
	}

	public String getCheer()
	{
		return cheer;
	}

	public Color getColor()
	{
		return color;
	}
}

package com.nextstep;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Animated celebration popup with spinning rays and confetti. Popups queue up and play one at a time. */
public class CelebrationOverlay extends Overlay
{
	private static final int BOX_W = 300;
	private static final int BOX_H = 112;
	private static final double INTRO_SECONDS = 0.35;
	private static final double OUTRO_SECONDS = 0.5;
	private static final double GRAVITY = 620;
	private static final int CONFETTI_COUNT = 110;
	private static final Color[] CONFETTI_COLORS = {
		new Color(255, 200, 60), new Color(90, 220, 110), new Color(100, 180, 255),
		new Color(255, 110, 170), new Color(190, 120, 255), new Color(255, 150, 60)
	};

	private final Client client;
	private final NextStepConfig config;
	private final Queue<Celebration> queue = new ConcurrentLinkedQueue<>();
	private final List<Particle> particles = new ArrayList<>();
	private volatile boolean clearRequested;

	private Celebration current;
	private long startNanos;
	private long lastNanos;

	@Inject
	CelebrationOverlay(Client client, NextStepConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void enqueue(Celebration celebration)
	{
		queue.add(celebration);
	}

	void clear()
	{
		queue.clear();
		clearRequested = true;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (clearRequested)
		{
			clearRequested = false;
			current = null;
			particles.clear();
		}

		long now = System.nanoTime();
		if (current == null)
		{
			current = queue.poll();
			if (current == null)
			{
				return null;
			}
			startNanos = now;
			lastNanos = now;
			particles.clear();
			if (config.confetti())
			{
				spawnConfetti();
			}
		}

		double t = (now - startNanos) / 1e9;
		double duration = config.popupSeconds();
		double dt = Math.min(0.05, (now - lastNanos) / 1e9);
		lastNanos = now;

		if (t >= duration)
		{
			current = null;
			particles.clear();
			return null;
		}

		int width = client.getCanvasWidth();
		int height = client.getCanvasHeight();
		int cx = width / 2;
		int cy = (int) (height * 0.3);
		float alpha = (float) clamp((duration - t) / OUTRO_SECONDS);
		double scale = Math.max(0.05, easeOutBack(clamp(t / INTRO_SECONDS)));

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			drawRays(g, cx, cy, t, scale);
			drawBox(g, cx, cy, scale);
			updateAndDrawConfetti(g, dt, height);
		}
		finally
		{
			g.dispose();
		}
		return null;
	}

	private void drawRays(Graphics2D g, int cx, int cy, double t, double scale)
	{
		Color c = current.getColor();
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 45));
		double radius = 210 * scale;
		int rays = 12;
		double half = Math.PI / rays * 0.45;
		double spin = t * 0.6;
		for (int i = 0; i < rays; i++)
		{
			double a = spin + i * 2 * Math.PI / rays;
			Path2D ray = new Path2D.Double();
			ray.moveTo(cx, cy);
			ray.lineTo(cx + Math.cos(a - half) * radius, cy + Math.sin(a - half) * radius);
			ray.lineTo(cx + Math.cos(a + half) * radius, cy + Math.sin(a + half) * radius);
			ray.closePath();
			g.fill(ray);
		}
	}

	private void drawBox(Graphics2D g, int cx, int cy, double scale)
	{
		AffineTransform old = g.getTransform();
		g.translate(cx, cy);
		g.scale(scale, scale);

		int x = -BOX_W / 2;
		int y = -BOX_H / 2;
		Color c = current.getColor();

		RoundRectangle2D box = new RoundRectangle2D.Double(x, y, BOX_W, BOX_H, 18, 18);
		g.setPaint(new GradientPaint(0, y, new Color(52, 44, 32), 0, y + BOX_H, new Color(24, 20, 15)));
		g.fill(box);
		g.setStroke(new BasicStroke(3f));
		g.setColor(c);
		g.draw(box);
		g.setStroke(new BasicStroke(1f));
		g.setColor(new Color(255, 255, 255, 40));
		g.draw(new RoundRectangle2D.Double(x + 5, y + 5, BOX_W - 10, BOX_H - 10, 12, 12));

		drawCentered(g, current.getTitle(), FontManager.getRunescapeBoldFont().deriveFont(24f), c, y + 30);
		drawCentered(g, current.getSubtitle(), FontManager.getRunescapeBoldFont().deriveFont(16f), Color.WHITE, y + 54);
		drawCentered(g, current.getDetail(), FontManager.getRunescapeFont().deriveFont(15f), new Color(210, 210, 210), y + 76);
		drawCentered(g, current.getCheer(), FontManager.getRunescapeSmallFont().deriveFont(14f), c.brighter(), y + 98);

		g.setTransform(old);
	}

	private void drawCentered(Graphics2D g, String text, Font font, Color color, int baseline)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(font);
		FontMetrics fm = g.getFontMetrics();
		String fitted = fit(text, fm, BOX_W - 24);
		int x = -fm.stringWidth(fitted) / 2;
		g.setColor(Color.BLACK);
		g.drawString(fitted, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(fitted, x, baseline);
	}

	private static String fit(String text, FontMetrics fm, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String s = text;
		while (s.length() > 1 && fm.stringWidth(s + "...") > maxWidth)
		{
			s = s.substring(0, s.length() - 1);
		}
		return s + "...";
	}

	private void spawnConfetti()
	{
		ThreadLocalRandom r = ThreadLocalRandom.current();
		double cx = client.getCanvasWidth() / 2.0;
		double cy = client.getCanvasHeight() * 0.3;
		for (int i = 0; i < CONFETTI_COUNT; i++)
		{
			Particle p = new Particle();
			double angle = r.nextDouble(-Math.PI, 0); // upward half
			double speed = r.nextDouble(200, 560);
			p.x = cx + r.nextDouble(-30, 30);
			p.y = cy + r.nextDouble(-10, 10);
			p.vx = Math.cos(angle) * speed;
			p.vy = Math.sin(angle) * speed;
			p.rot = r.nextDouble(0, Math.PI * 2);
			p.vrot = r.nextDouble(-8, 8);
			p.size = r.nextDouble(4, 9);
			p.color = CONFETTI_COLORS[r.nextInt(CONFETTI_COLORS.length)];
			particles.add(p);
		}
	}

	private void updateAndDrawConfetti(Graphics2D g, double dt, int canvasHeight)
	{
		Iterator<Particle> it = particles.iterator();
		while (it.hasNext())
		{
			Particle p = it.next();
			p.vy += GRAVITY * dt;
			p.vx *= (1 - 0.8 * dt);
			p.x += p.vx * dt;
			p.y += p.vy * dt;
			p.rot += p.vrot * dt;
			if (p.y > canvasHeight + 20)
			{
				it.remove();
				continue;
			}
			AffineTransform old = g.getTransform();
			g.translate(p.x, p.y);
			g.rotate(p.rot);
			g.setColor(p.color);
			int w = (int) Math.round(p.size);
			int h = Math.max(2, w / 2);
			g.fillRect(-w / 2, -h / 2, w, h);
			g.setTransform(old);
		}
	}

	private static double clamp(double v)
	{
		return Math.max(0, Math.min(1, v));
	}

	/** Overshoots slightly then settles: gives the popup a "pop". */
	private static double easeOutBack(double x)
	{
		double c1 = 1.70158;
		double c3 = c1 + 1;
		return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
	}

	private static final class Particle
	{
		double x;
		double y;
		double vx;
		double vy;
		double rot;
		double vrot;
		double size;
		Color color;
	}
}

package com.nextstep;

import java.util.List;

/** A Suggestion checked against the player's current account. Immutable. */
public class EvaluatedSuggestion
{
	public enum Status
	{
		DONE,
		READY,
		ALMOST,
		LOCKED
	}

	private final Suggestion suggestion;
	private final Status status;
	private final int levelGap;
	private final List<String> missing;
	private final List<String> recWarnings;
	private final double progress;
	private final boolean inProgress;
	private int distance = -1;   // tiles from the player, -1 if unknown
	private String compass;      // short direction like "NE"

	public EvaluatedSuggestion(Suggestion suggestion, Status status, int levelGap, List<String> missing,
		List<String> recWarnings, double progress, boolean inProgress)
	{
		this.suggestion = suggestion;
		this.status = status;
		this.levelGap = levelGap;
		this.missing = missing;
		this.recWarnings = recWarnings;
		this.progress = progress;
		this.inProgress = inProgress;
	}

	public Suggestion getSuggestion()
	{
		return suggestion;
	}

	public String getName()
	{
		return suggestion.getName();
	}

	public Status getStatus()
	{
		return status;
	}

	public int getLevelGap()
	{
		return levelGap;
	}

	public List<String> getMissing()
	{
		return missing;
	}

	public List<String> getRecWarnings()
	{
		return recWarnings;
	}

	public double getProgress()
	{
		return progress;
	}

	public boolean isInProgress()
	{
		return inProgress;
	}

	public int getDistance()
	{
		return distance;
	}

	public String getCompass()
	{
		return compass;
	}

	void setDistance(int distance, String compass)
	{
		this.distance = distance;
		this.compass = compass;
	}

	/** Done quest, or a non-quest whose requirements are all met. */
	public boolean isAchieved()
	{
		return status == Status.DONE
			|| (status == Status.READY && suggestion.getType() != Suggestion.Type.QUEST);
	}
}

package com.nextstep;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** On-screen box showing the pinned goal and live directions to where you're headed. */
public class GoalOverlay extends OverlayPanel
{
	private static final Color ORANGE = new Color(224, 160, 80);
	private static final Color TIP_GRAY = new Color(180, 180, 180);

	private final NextStepPlugin plugin;
	private final NextStepConfig config;

	@Inject
	GoalOverlay(NextStepPlugin plugin, NextStepConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(200, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGoalOverlay())
		{
			return null;
		}
		EvaluatedSuggestion goal = plugin.getPinnedEval();
		GuideInfo guide = config.showDirections() ? plugin.getGuideInfo() : null;
		if (goal == null && guide == null)
		{
			return null;
		}

		if (goal != null)
		{
			renderGoal(goal);
		}

		if (guide != null)
		{
			boolean sameAsGoal = goal != null && goal.getName().equals(guide.name);
			if (!sameAsGoal)
			{
				panelComponent.getChildren().add(TitleComponent.builder()
					.text("Guiding: " + guide.name)
					.color(Celebration.BLUE)
					.build());
			}
			if (guide.locationName != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Go to: " + guide.locationName)
					.leftColor(Color.WHITE)
					.build());
			}
			if (guide.directions != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(guide.directions)
					.leftColor(guide.directions.startsWith("You're here") ? Celebration.GREEN : Celebration.BLUE)
					.build());
			}
			if (guide.travelTip != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Tip: " + guide.travelTip)
					.leftColor(TIP_GRAY)
					.build());
			}
		}
		return super.render(graphics);
	}

	private void renderGoal(EvaluatedSuggestion goal)
	{
		int pct = (int) Math.round(goal.getProgress() * 100);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Goal: " + goal.getName())
			.color(Celebration.GOLD)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Progress")
			.right(pct + "%")
			.rightColor(pct >= 100 ? Celebration.GREEN : Color.WHITE)
			.build());

		if (goal.getStatus() == EvaluatedSuggestion.Status.READY)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Ready! Go do it.")
				.leftColor(Celebration.GREEN)
				.build());
			return;
		}
		int shown = 0;
		for (String m : goal.getMissing())
		{
			if (shown++ >= 3)
			{
				break;
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left(m)
				.leftColor(ORANGE)
				.build());
		}
	}
}

package com.nextstep;

/** What the overlay needs to show directions. Immutable. */
public class GuideInfo
{
	final String name;
	final String locationName;
	final String travelTip;
	final String directions; // may be null (no coordinates, or unknown)

	GuideInfo(String name, String locationName, String travelTip, String directions)
	{
		this.name = name;
		this.locationName = locationName;
		this.travelTip = travelTip;
		this.directions = directions;
	}
}

package com.nextstep;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/** Small custom-painted progress bar (avoids look-and-feel quirks of JProgressBar). */
class MiniBar extends JComponent
{
	private static final int HEIGHT = 14;

	private final double fraction;
	private final Color color;
	private final String text;

	MiniBar(double fraction, Color color, String text)
	{
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.color = color;
		this.text = text;
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			g.setColor(new Color(30, 30, 30));
			g.fillRoundRect(0, 0, w, h, 6, 6);
			g.setColor(color.darker());
			g.fillRoundRect(0, 0, (int) Math.round(w * fraction), h, 6, 6);

			if (text != null)
			{
				g.setFont(FontManager.getRunescapeSmallFont());
				FontMetrics fm = g.getFontMetrics();
				int tx = (w - fm.stringWidth(text)) / 2;
				int ty = (h - fm.getHeight()) / 2 + fm.getAscent();
				g.setColor(Color.BLACK);
				g.drawString(text, tx + 1, ty + 1);
				g.setColor(Color.WHITE);
				g.drawString(text, tx, ty);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.nextstep;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Shows the way to a destination: world map marker, hint arrow when close,
 * and (if installed) a walking route from the Shortest Path plugin.
 * All methods must be called on the client thread.
 */
@Singleton
class Navigator
{
	/** Dungeons/instances live at y >= 6400; surface directions don't apply there. */
	private static final int UNDERGROUND_Y = 6400;
	private static final int HINT_ARROW_RANGE = 40;
	private static final String[] COMPASS_LONG = {
		"north", "north-east", "east", "south-east", "south", "south-west", "west", "north-west"
	};
	private static final String[] COMPASS_SHORT = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

	private final Client client;
	private final WorldMapPointManager worldMapPointManager;
	private final EventBus eventBus;
	private final NextStepConfig config;
	private final BufferedImage markerImage = buildMarker();

	private WorldMapPoint mapPoint;
	private WorldPoint target;
	private boolean pathRequested;

	@Inject
	Navigator(Client client, WorldMapPointManager worldMapPointManager, EventBus eventBus, NextStepConfig config)
	{
		this.client = client;
		this.worldMapPointManager = worldMapPointManager;
		this.eventBus = eventBus;
		this.config = config;
	}

	void navigateTo(Suggestion s)
	{
		clear();
		target = s.getLocation();
		if (target == null)
		{
			return;
		}

		if (config.mapMarker())
		{
			mapPoint = new WorldMapPoint(target, markerImage);
			mapPoint.setTooltip("Next Step: " + s.getName() + " - " + s.getLocationName());
			mapPoint.setJumpOnClick(true);
			mapPoint.setSnapToEdge(true);
			worldMapPointManager.add(mapPoint);
		}

		if (config.shortestPath())
		{
			// Ignored harmlessly if the Shortest Path plugin isn't installed.
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			eventBus.post(new PluginMessage("shortestpath", "path", data));
			pathRequested = true;
		}
	}

	/** Call every tick while navigating: keeps the hint arrow up when close. */
	void tick(WorldPoint player)
	{
		if (target == null || player == null || !config.hintArrow())
		{
			return;
		}
		int dist = distance(player, target);
		if (dist >= 0 && dist <= HINT_ARROW_RANGE && !client.hasHintArrow())
		{
			client.setHintArrow(target);
		}
	}

	void clear()
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
		if (target != null && client.hasHintArrow() && target.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		if (pathRequested)
		{
			eventBus.post(new PluginMessage("shortestpath", "clear", new HashMap<>()));
			pathRequested = false;
		}
		target = null;
	}

	WorldPoint getTarget()
	{
		return target;
	}

	// ---------------- Direction helpers ----------------

	/** Tile distance on the surface, or -1 if either point is underground. */
	static int distance(WorldPoint from, WorldPoint to)
	{
		if (from == null || to == null || from.getY() >= UNDERGROUND_Y || to.getY() >= UNDERGROUND_Y)
		{
			return -1;
		}
		return Math.max(Math.abs(to.getX() - from.getX()), Math.abs(to.getY() - from.getY()));
	}

	static String compassShort(WorldPoint from, WorldPoint to)
	{
		return COMPASS_SHORT[compassIndex(from, to)];
	}

	/** Friendly direction text, e.g. "Head north-west (~340 tiles)". */
	static String describe(WorldPoint from, WorldPoint to)
	{
		if (from == null || to == null)
		{
			return null;
		}
		if (from.getY() >= UNDERGROUND_Y)
		{
			return "You're underground; head to the surface";
		}
		int dist = distance(from, to);
		if (dist < 0)
		{
			return null;
		}
		if (dist <= 8)
		{
			if (to.getPlane() > from.getPlane())
			{
				return "Right here! Go upstairs";
			}
			if (to.getPlane() < from.getPlane())
			{
				return "Right here! Go downstairs";
			}
			return "You're here!";
		}
		return "Head " + COMPASS_LONG[compassIndex(from, to)] + " (~" + dist + " tiles)";
	}

	private static int compassIndex(WorldPoint from, WorldPoint to)
	{
		int dx = to.getX() - from.getX();
		int dy = to.getY() - from.getY(); // north is +y
		double angle = Math.toDegrees(Math.atan2(dx, dy)); // 0 = north, 90 = east
		double normalized = ((angle % 360) + 360) % 360;
		return (int) Math.round(normalized / 45.0) % 8;
	}

	private static BufferedImage buildMarker()
	{
		BufferedImage img = new BufferedImage(20, 26, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Path2D pin = new Path2D.Double();
		pin.moveTo(10, 25);
		pin.curveTo(3, 15, 1, 12, 1, 9);
		pin.curveTo(1, 4, 5, 1, 10, 1);
		pin.curveTo(15, 1, 19, 4, 19, 9);
		pin.curveTo(19, 12, 17, 15, 10, 25);
		pin.closePath();
		g.setColor(new Color(255, 200, 60));
		g.fill(pin);
		g.setColor(Color.BLACK);
		g.setStroke(new BasicStroke(1.5f));
		g.draw(pin);
		g.setColor(new Color(40, 30, 10));
		g.fill(new Ellipse2D.Double(6, 5, 8, 8));
		g.dispose();
		return img;
	}
}

